;; Generated by `bops gen clj` from bops/commands.json (contract 1). Do not edit.
(ns bops
  "One fn per bops command (bops/commands.json), each shelling out to
   `bops <command> --json` and returning {:exit n :doc parsed-json :err stderr}.
   Exit 0 is done, 1 could not run, 2 usage, 3 a negative verdict (lost,
   refused): a verdict, not a failure, so no fn throws on an exit status. They
   throw only on a bad call (a missing required option, an unknown one)
   before bops runs. Every fn takes cfg first: :bops-path (default \"bops\")
   and :actor (passed as BEADS_ACTOR). Needs babashka.process and cheshire
   (built into Babashka) and Malli."
  (:refer-clojure :exclude [next sync])
  (:require [babashka.process :as p]
            [cheshire.core :as json]
            [clojure.string :as str]
            [malli.core :as m]))

(def contract
  "The bops contract this namespace was generated for. bops refuses nothing on
   a mismatch, so check it against (:contract (:doc (version {})))."
  1)

(def envelope
  "Malli schema of the fields every result carries, including a run that
   could not complete (exit 1 or 2)."
  [:map [:code {:optional true} [:maybe :string]] [:command :string] [:contract :int] [:error {:optional true} [:maybe :string]] [:ok :boolean]])

(def ^:private specs
  "Per command: whether it takes the bead id, how it takes text (:required
   on stdin, :optional on stdin with --file -), and each option's kind."
  {"next" {:id? false :text nil :opts {:avoid-conflicts :bool, :caps :list, :include-unworkable :bool, :n :value, :pool :value} :required #{}}
   "claim" {:id? :optional :text nil :opts {:force :bool, :next :bool, :resume :bool} :required #{}}
   "note" {:id? true :text :required :opts {:op-id :value} :required #{}}
   "renew" {:id? true :text nil :opts {} :required #{}}
   "release" {:id? true :text :optional :opts {:op-id :value, :reason :value} :required #{:reason}}
   "land" {:id? true :text nil :opts {:forge :value, :op-id :value, :ref :value, :sha :value, :verify :bool} :required #{:ref :sha}}
   "sweep" {:id? false :text nil :opts {:dry-run :bool, :forge :value} :required #{}}
   "stale" {:id? false :text nil :opts {:all-machines :bool, :older-than :value} :required #{}}
   "status" {:id? false :text nil :opts {:mine :bool, :older-than :value, :stale :bool} :required #{}}
   "reap" {:id? false :text nil :opts {:dry-run :bool, :forge :value, :older-than :value, :only :value} :required #{}}
   "gc" {:id? false :text nil :opts {:dry-run :bool, :only :value} :required #{}}
   "lint" {:id? true :text nil :opts {:strict :bool} :required #{}}
   "sync" {:id? false :text nil :opts {:no-push :bool} :required #{}}
   "session-start" {:id? false :text nil :opts {:hook-json :bool} :required #{}}
   "doctor" {:id? false :text nil :opts {} :required #{}}
   "gates" {:id? true :text nil :opts {} :required #{}}
   "deps" {:id? true :text nil :opts {:engine :value, :path :bool, :transitive :bool} :required #{}}
   "version" {:id? false :text nil :opts {} :required #{}}})

