   "claim" [:map [:age_minutes {:optional true} [:maybe :int]] [:claimed_at {:optional true} [:maybe :string]] [:code {:optional true} [:maybe :string]] [:command :string] [:contract :int] [:error {:optional true} [:maybe :string]] [:generation {:optional true} [:maybe :int]] [:holder {:optional true} [:maybe :map]] [:id :string] [:ledger_pending {:optional true} [:maybe :boolean]] [:next_candidate {:optional true} [:maybe :string]] [:ok :boolean] [:outcome :string] [:previous {:optional true} [:maybe :map]] [:readback_ok {:optional true} [:maybe :boolean]] [:reason {:optional true} [:maybe :string]] [:ref_pending {:optional true} [:maybe :boolean]] [:retry {:optional true} [:maybe :string]] [:run :string] [:side_effects {:optional true} [:maybe :string]] [:skipped {:optional true} [:maybe [:vector :map]]] [:stale_minutes {:optional true} [:maybe :int]] [:warnings {:optional true} [:maybe [:vector :string]]]]
   "note" [:map [:code {:optional true} [:maybe :string]] [:command :string] [:comment_id {:optional true} [:maybe :string]] [:contract :int] [:error {:optional true} [:maybe :string]] [:holder {:optional true} [:maybe :map]] [:id :string] [:ok :boolean] [:op_id {:optional true} [:maybe :string]] [:outcome :string] [:reason {:optional true} [:maybe :string]] [:replayed {:optional true} [:maybe :boolean]] [:saved_to {:optional true} [:maybe :string]] [:warnings [:vector :string]]]
   "renew" [:map [:beads [:vector [:map [:code {:optional true} [:maybe :string]] [:holder {:optional true} [:maybe :map]] [:id :string] [:outcome [:enum "renewed" "lost" "refused" "unreachable" "error"]] [:reason {:optional true} [:maybe :string]]]]] [:code {:optional true} [:maybe :string]] [:command :string] [:contract :int] [:error {:optional true} [:maybe :string]] [:ok :boolean] [:warnings [:vector :string]]]
