(defn run
  "Run bops with argv and --json. Never throws on an exit status: returns
   {:exit n :doc parsed-json-or-nil :err stderr}. cfg's :in, when set, is
   written to bops's stdin."
  [{:keys [bops-path actor in] :or {bops-path "bops"}} & argv]
  (let [opts (cond-> {:continue true}
               actor (assoc :extra-env {"BEADS_ACTOR" actor})
               in    (assoc :in in))
        {:keys [exit out err]} (apply p/sh opts bops-path (concat argv ["--json"]))]
    {:exit exit
     :err  err
     :doc  (try (json/parse-string out true) (catch Exception _ nil))}))

(defn argv
  "Pure: the command line for command, the bead id (nil when it takes none)
   and opts, by its spec. Options in name order, then --file - for optional
   text. Throws ex-info on a missing id, text or required option, and on an
   option the command does not take."
  [command id opts]
  (let [{:keys [id? text required] :as spec} (or (specs command)
                                                 (throw (ex-info (str "bops has no command " command) {:command command})))
        kinds (:opts spec)
        extra (remove (conj (set (keys kinds)) :text) (keys opts))]
    (when (seq extra)
      (throw (ex-info (str "bops " command " takes no option " (str/join ", " extra)) {:command command :options extra})))
    (when (and (true? id?) (str/blank? id))
      (throw (ex-info (str "bops " command " needs a bead id") {:command command})))
    (when (and id? (string? id) (str/starts-with? id "-"))
      (throw (ex-info (str "bops " command ": a bead id must not start with -") {:command command :id id})))
    (when (and (= :required text) (str/blank? (:text opts)))
      (throw (ex-info (str "bops " command " needs text") {:command command})))
    (doseq [k required]
      (when (nil? (get opts k))
        (throw (ex-info (str "bops " command " needs " k) {:command command :option k}))))
    (-> [command]
        (cond-> (and id? (not (str/blank? id))) (conj id))
        (into (mapcat (fn [[k kind]]
                        (let [v (get opts k) flag (str "--" (name k))]
                          (cond
                            ;; An explicit nil --only is an empty list (refused), never "no filter".
                            (and (nil? v) (#{"reap" "gc"} command) (= k :only) (contains? opts k)) [(str flag "=")]
                            (nil? v)       []
                            (= kind :bool) [(if v flag (str flag "=false"))]
                            (= kind :list) [flag (str/join "," v)]
                            :else          [flag (str v)])))
                      (sort-by key kinds)))
        (cond-> (and (= :optional text) (:text opts)) (conj "--file" "-")))))

(defn call
  "Run command with the bead id (nil when it takes none) and opts, sending
   (:text opts) on stdin. Returns run's map."
  [cfg command id opts]
  (let [args (argv command id opts)
        cfg  (cond-> cfg (:text opts) (assoc :in (:text opts)))]
    (apply run cfg args)))

(defn valid?
  "Whether doc, a parsed result of command from a run that completed (exit 0
   or 3), matches its output schema. Check a run that could not complete
   (exit 1 or 2) against envelope."
  [command doc]
  (m/validate (output command) doc))

(defn explain
  "Malli's explanation of why doc does not match command's output, or nil."
  [command doc]
  (m/explain (output command) doc))

(defn next
  "What should I work on?. Runs `bops next`; returns {:exit :doc :err}.\n   opts: :avoid-conflicts (bool); :caps (string[]?); :include-unworkable (bool); :n (int); :pool (string?)."
  ([cfg] (next cfg {}))
  ([cfg opts] (call cfg "next" nil opts)))

(defn claim
  "Take this bead for this run. Runs `bops claim`; returns {:exit :doc :err}. id may be nil.\n   opts: :force (bool); :next (bool); :resume (bool)."
  ([cfg id] (claim cfg id {}))
  ([cfg id opts] (call cfg "claim" id opts)))

(defn note
  "Record where I am, keep the claim. Runs `bops note`; returns {:exit :doc :err}.\n   opts: :op-id (string?).\n   text is sent on stdin."
  ([cfg id text] (note cfg id text {}))
  ([cfg id text opts] (call cfg "note" id (assoc opts :text text))))

(defn renew
  "Heartbeat my claims, no comment. Runs `bops renew`; returns {:exit :doc :err}."
  ([cfg id] (renew cfg id {}))
  ([cfg id opts] (call cfg "renew" id opts)))

(defn release
  "Give the claim back. Runs `bops release`; returns {:exit :doc :err}.\n   opts: :op-id (string?); :reason (one of done, blocked, scope, abandoned, human, required); :text (string, sent on stdin)."
  ([cfg id] (release cfg id {}))
  ([cfg id opts] (call cfg "release" id opts)))

(defn land
  "Record that work reached its destination. Runs `bops land`; returns {:exit :doc :err}.\n   opts: :forge (one of auto, github, gitlab, none); :op-id (string?); :ref (url, required); :sha (string, required); :verify (bool)."
  ([cfg id] (land cfg id {}))
  ([cfg id opts] (call cfg "land" id opts)))

(defn sweep
  "Close landed beads whose refs are merged. Runs `bops sweep`; returns {:exit :doc :err}.\n   opts: :dry-run (bool); :forge (one of auto, github, gitlab, none)."
  ([cfg] (sweep cfg {}))
  ([cfg opts] (call cfg "sweep" nil opts)))

(defn stale
  "Claims nobody is working. Runs `bops stale`; returns {:exit :doc :err}.\n   opts: :all-machines (bool); :older-than (duration)."
  ([cfg] (stale cfg {}))
  ([cfg opts] (call cfg "stale" nil opts)))

(defn status
  "Every claim on every machine. Runs `bops status`; returns {:exit :doc :err}.\n   opts: :mine (bool); :older-than (duration); :stale (bool)."
  ([cfg] (status cfg {}))
  ([cfg opts] (call cfg "status" nil opts)))

(defn reap
  "Release stale claims that hold no work. Runs `bops reap`; returns {:exit :doc :err}.\n   opts: :dry-run (bool); :forge (one of auto, github, gitlab, none); :older-than (duration); :only (string?)."
  ([cfg] (reap cfg {}))
  ([cfg opts] (call cfg "reap" nil opts)))

(defn gc
  "Delete refs of closed beads and orphans. Runs `bops gc`; returns {:exit :doc :err}.\n   opts: :dry-run (bool); :only (string?)."
  ([cfg] (gc cfg {}))
  ([cfg opts] (call cfg "gc" nil opts)))

(defn lint
  "Is this bead workable?. Runs `bops lint`; returns {:exit :doc :err}.\n   opts: :strict (bool)."
  ([cfg id] (lint cfg id {}))
  ([cfg id opts] (call cfg "lint" id opts)))

(defn sync
  "Pull, heartbeat, push — with the one retry. Runs `bops sync`; returns {:exit :doc :err}.\n   opts: :no-push (bool)."
  ([cfg] (sync cfg {}))
  ([cfg opts] (call cfg "sync" nil opts)))

(defn session-start
  "Orient a fresh agent session. Runs `bops session-start`; returns {:exit :doc :err}.\n   opts: :hook-json (bool)."
  ([cfg] (session-start cfg {}))
  ([cfg opts] (call cfg "session-start" nil opts)))

(defn doctor
  "Can the claim lock work against its remote (lock.remote, default origin)?. Runs `bops doctor`; returns {:exit :doc :err}."
  ([cfg] (doctor cfg {}))
  ([cfg opts] (call cfg "doctor" nil opts)))

(defn gates
  "What is blocking this bead's path?. Runs `bops gates`; returns {:exit :doc :err}."
  ([cfg id] (gates cfg id {}))
  ([cfg id opts] (call cfg "gates" id opts)))

(defn deps
  "Blockers, dependents, longest path. Runs `bops deps`; returns {:exit :doc :err}.\n   opts: :engine (one of bd, cte, graph); :path (bool); :transitive (bool)."
  ([cfg id] (deps cfg id {}))
  ([cfg id opts] (call cfg "deps" id opts)))

(defn version
  "Report bops, contract, and detected bd. Runs `bops version`; returns {:exit :doc :err}."
  ([cfg] (version cfg {}))
  ([cfg opts] (call cfg "version" nil opts)))
